b = float(input('Δώσε το b: '))c = float(input('Δώσε το c: '))L = float(input('Δώσε το L: '))R = float(input('Δώσε το R, με L<R: '))print('Εξίσωση: x^2+bx+c, b =', format(b, '.2f'), ', c =', \      format(c, '.2f'))print('Διάστημα: [L,R], L =', format(L, '.2f'), ', R =', \      format(R, '.2f'))# Υπολογισμός κρίσιμου σημείουxc= - b/2if xc < L:    xmin = Lelif L <= xc and xc <=R:    xmin = xcelse:    xmin = Rfmin = xmin**2 + b*xmin + cprint('x ελαχιστοποίησης =', format(xmin, '.2f'))print('Ελάχιστη τιμή της f =', format(fmin, '.2f'))